    dx = (x1 > x0) - (x1 < x0); dy = (y1 > y0) - (y1 < y0)
    cnt = 0
    for k in range(n):
        p = Position(x=x0+dx*k, y=y0+dy*k)
        if k % 6 == 0: move_to(p)
        try:
            place_entity(Prototype.TransportBelt, position=p, direction=d)
            cnt += 1
        except Exception as e:
            print("belt err", p, e)
    return cnt
